using Confectory.Core;
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;

// Pure same-owner schema/default candidate. Other information declarations,
// object data and typed graph callers are validated, never rewritten here.
internal static class InformationDefinitions
{
 static string Hash(string text)=>JsonData.HashBytes(Encoding.UTF8.GetBytes(text));
 static void Exact(JsonObject row,params string[] keys){if(row.Count!=keys.Length||row.Any(p=>!keys.Contains(p.Key,StringComparer.Ordinal)))throw new ArgumentException("Exact information edit required");}
 public static JsonObject Prepare(JsonObject request,Func<Element,string> format,Func<Manifest,string> formatManifest)
 {
  string project=request["project"]!.GetValue<string>(),manifest=request["manifest"]!.GetValue<string>(),id=request["id"]!.GetValue<string>(),text=request["text"]!.GetValue<string>();var schema=new Parser(text,"<information-owner>").ParseElement();var registration=new Parser(manifest,"<information-registration>").ParseManifest();var drafts=request["drafts"]!.AsArray();var changes=request["changes"]!.AsArray();if(schema.Kind!="schema"||schema.Id!=id||!id.StartsWith(registration.Namespace+"::",StringComparison.Ordinal)||registration.Kind!="project"||changes.Count is <1 or >64||drafts.Count>255)throw new ArgumentException("Bounded owned information candidate required");
  string Read(string path){var file=new FileInfo(path);if(!file.Exists||file.Length>1048576)throw new IOException("Information source budget");return File.ReadAllText(path);}
  JsonObject Inspect(string source,bool types=false)=>EffectiveMetadata.Query(project,manifest,id,source,formatManifest,Read,drafts,schemaView:true,validateObjects:true,observeSources:true,definitionTypes:types);
  var before=Inspect(text,changes.Any(c=>c?["type"]?.ToString()=="typed-definition"||c?["definition"] is not null));if(before["status"]?.ToString()!="available"||before["schemaModel"]?["validation"]?["status"]?.ToString()!="valid")throw new InvalidOperationException("Original information/default graph invalid; retain input");var model=before["schemaModel"]!.AsObject();var values=new JsonObject();JsonNode Transport(JsonNode datum)=>datum["kind"]!.ToString() switch{"reference"=>new JsonObject{["$ref"]=datum["reference"]!.DeepClone()},"multiple"=>new JsonArray(datum["items"]!.AsArray().Select(v=>Transport(v!)).ToArray()),"compound"=>new JsonObject(datum["members"]!.AsObject().Select(p=>KeyValuePair.Create<string,JsonNode?>(p.Key,Transport(p.Value!)))),_=>datum["scalar"]!.DeepClone()};foreach(var pair in model["data"]!.AsObject())values[pair.Key]=Transport(pair.Value!);using var parsedValues=JsonDocument.Parse(values.ToJsonString());var dataOwner=new Element{Id=id,Kind="object",Data=SchemaContracts.FromTransport(parsedValues.RootElement,id).Members!};var seen=new HashSet<string>(StringComparer.Ordinal);var paths=new List<JsonArray>();
  void Unique(string key){if(!seen.Add(key))throw new ArgumentException("Duplicate information edit");}
  void Label(string field,string label){label=label.Trim();if(label.Length is <1 or >60||label.Any(char.IsControl))throw new ArgumentException("Bounded distinct information display name required");if(label==field)schema.Values.Remove("editorFieldName_"+field);else schema.Values["editorFieldName_"+field]=new(JsonSerializer.SerializeToElement(label),id,new());}
  foreach(var item in changes){var row=item!.AsObject();string type=row["type"]!.ToString();if(type=="description"){Exact(row,"type","text");Unique(type);string value=row["text"]!.GetValue<string>();if(value.Length>16384)throw new ArgumentException("Description budget");schema.Description=value;schema.DescriptionPresent=true;continue;}
   if(type=="modules"){
    Exact(row,"type","ids");Unique(type);var ids=row["ids"]!.AsArray();if(ids.Count>32||ids.Select(v=>v!.GetValue<string>()).Distinct(StringComparer.Ordinal).Count()!=ids.Count)throw new ArgumentException("Bounded distinct information modules required");
    DeclarationAuthoring.Apply(schema,new JsonObject{["action"]="relations",["role"]="module",["entries"]=new JsonArray(ids.Select(v=>(JsonNode)new JsonObject{["id"]=v!.DeepClone()}).ToArray())});continue;
   }
   if(type is "data" or "unset"){
    Exact(row,type=="data"?new[]{"type","path","contract","valueJson"}:new[]{"type","path","contract"});var path=row["path"]!.AsArray();var shape=MixedOwnerCopyEdits.Field(model,path);if(!JsonNode.DeepEquals(shape,row["contract"]))throw new InvalidOperationException("Information field contract changed");foreach(var prior in paths)if(prior.Take(Math.Min(prior.Count,path.Count)).Select(v=>v!.ToJsonString()).SequenceEqual(path.Take(Math.Min(prior.Count,path.Count)).Select(v=>v!.ToJsonString())))throw new ArgumentException("Overlapping information default edits require explicit reconciliation");paths.Add(path);string field=path[0]!.ToString();if(type=="unset"){if(path.Count!=1||!schema.Values.Remove(InformationDefaults.Prefix+field))throw new ArgumentException("Only a stored local root default may be reset");continue;}string json=row["valueJson"]!.GetValue<string>();if(json.Length>65536)throw new ArgumentException("Information default budget");using var value=JsonDocument.Parse(json);SchemaContracts.SetDataPath(dataOwner,JsonSerializer.SerializeToElement(path),value.RootElement);InformationDefaults.Set(schema,field,dataOwner.Data[field]);continue;
   }
   if(type is "schema-name" or "schema-remove" or "schema-field"){
    Exact(row,type=="schema-name"?new[]{"type","path","contract","schema","schemaHash","name"}:type=="schema-remove"?new[]{"type","path","contract","schema","schemaHash"}:row["definition"] is null?new[]{"type","path","contract","schema","schemaHash","nativeType"}:new[]{"type","path","contract","schema","schemaHash","definition","sources"});var path=row["path"]!.AsArray();if(path.Count!=1||row["schema"]?.ToString()!=id||row["schemaHash"]?.ToString()!=Hash(text)||!schema.Fields.TryGetValue(path[0]!.ToString(),out var original)||!JsonNode.DeepEquals(MixedOwnerCopyEdits.Field(model,path),row["contract"]))throw new InvalidOperationException("Direct unchanged information definition required");string field=path[0]!.ToString();Unique(type+":"+field);if(type=="schema-name")Label(field,row["name"]!.GetValue<string>());else if(type=="schema-remove"){if(changes.Any(other=>!ReferenceEquals(row,other)&&other?["path"]?[0]?.ToString()==field))throw new ArgumentException("Keep other field input before explicit deletion");schema.Fields.Remove(field);schema.Values.Remove("editorFieldName_"+field);schema.Values.Remove(InformationDefaults.Prefix+field);}else{var shape=FieldTypes.Contract(row);FieldTypes.Validate(shape,row["sources"],before["definitionTypes"] as JsonArray??new());SchemaContracts.SetField(schema,field,JsonSerializer.SerializeToElement(shape));}continue;
   }
   if(type=="typed-definition"){
    Exact(row,"type","name","displayName","contract","sources","valueJson");string field=row["name"]!.GetValue<string>();Unique("definition:"+field);if(model["fields"]?[field] is not null||schema.Fields.ContainsKey(field))throw new ArgumentException("New stable information field identity required");var shape=row["contract"]!.AsObject();FieldTypes.Validate(shape,row["sources"],before["definitionTypes"]!.AsArray());SchemaContracts.SetField(schema,field,JsonSerializer.SerializeToElement(shape));Label(field,row["displayName"]!.GetValue<string>());string json=row["valueJson"]!.GetValue<string>();if(json.Length>65536)throw new ArgumentException("Information default budget");using var value=JsonDocument.Parse(json);InformationDefaults.Set(schema,field,SchemaContracts.FromTransport(value.RootElement,id));continue;
   }
   if(type=="info-definition"){
    Exact(row,"type","name","displayName","contract","sources","valueJson");string field=row["name"]!.GetValue<string>();Unique("definition:"+field);if(model["fields"]?[field] is not null||schema.Fields.ContainsKey(field))throw new ArgumentException("New stable information field identity required");var shape=row["contract"]!.AsObject();if(shape.Count!=3||shape["cardinality"]?.ToString()!="single")throw new ArgumentException("Explicit single information field required");if(shape["kind"]?.ToString()=="compound"){var catalogue=InformationTypes.Query(new JsonObject{["project"]=project,["manifest"]=manifest,["drafts"]=new JsonArray(drafts.Select(d=>d!.DeepClone()).Append(new JsonObject{["id"]=id,["text"]=text}).ToArray())},formatManifest);var choice=catalogue.SingleOrDefault(v=>v!["id"]!.ToString()==shape["type"]!.ToString());if(choice?["available"]?.GetValue<bool>()!=true||!JsonNode.DeepEquals(choice["sources"],row["sources"]))throw new InvalidOperationException("Selected nested information changed");}else if(shape["kind"]?.ToString()!="general"||row["sources"] is not null||shape["type"]?.ToString() is not ("string" or "bool" or "int" or "long" or "float" or "double"))throw new ArgumentException("Supported information field type required");SchemaContracts.SetField(schema,field,JsonSerializer.SerializeToElement(shape));Label(field,row["displayName"]!.GetValue<string>());string json=row["valueJson"]!.GetValue<string>();if(json.Length>65536)throw new ArgumentException("Information default budget");using var value=JsonDocument.Parse(json);InformationDefaults.Set(schema,field,SchemaContracts.FromTransport(value.RootElement,id));continue;
   }
   throw new ArgumentException("Information edit is not connected by the original editor");
  }
  if(schema.Fields.Select(p=>schema.Values.TryGetValue("editorFieldName_"+p.Key,out var label)&&label.Value.ValueKind==JsonValueKind.String?label.Value.GetString():p.Key).Distinct(StringComparer.OrdinalIgnoreCase).Count()!=schema.Fields.Count)throw new ArgumentException("Distinct information field display names required");string updated=DeclarationTextMerge.Merge(text,format(schema),text,format);if(updated.Length>1048576)throw new ArgumentException("Information result budget");var after=Inspect(updated);if(after["status"]?.ToString()!="available"||after["schemaModel"]?["validation"]?["status"]?.ToString()!="valid")throw new InvalidOperationException("Information type/default conflicts with existing values or references; no changes applied");var observations=new SortedDictionary<string,JsonNode>(OperatingSystem.IsWindows()?StringComparer.OrdinalIgnoreCase:StringComparer.Ordinal);foreach(var observation in before["observations"]!.AsArray().Concat(after["observations"]!.AsArray())){string path=observation!["path"]!.GetValue<string>();if(observations.TryGetValue(path,out var prior)&&!JsonNode.DeepEquals(prior,observation))throw new InvalidOperationException("Information dependencies changed while preparing candidate; no changes applied");observations[path]=observation.DeepClone();}if(observations.Count>2048)throw new ArgumentException("Information dependency budget");foreach(var observation in observations)if(Hash(Read(observation.Key))!=observation.Value["hash"]!.ToString())throw new InvalidOperationException("Information dependencies changed after validation; no changes applied");return new(){["text"]=updated,["manifest"]=manifest,["additions"]=new JsonArray(),["updates"]=new JsonArray(),["observations"]=new JsonArray(observations.Values.Select(v=>v.DeepClone()).ToArray()),["sourceWritten"]=false,["compiled"]=false};
 }
}
